\section{Introduction}

\subsection{Provability as a modality}

G\"odel's arithmetisation of syntax makes a sufficiently strong arithmetical theory capable of
expressing a provability predicate. The Hilbert--Bernays--L\"ob derivability conditions isolate
three properties of this predicate that suffice for the incompleteness phenomena, and
\emph{provability logic} abstracts them into a modal operator $\Box$:
\begin{enumerate}
  \item \textbf{Distribution.} $\vdash \Box(A \to B) \to (\Box A \to \Box B)$.
  \item \textbf{Necessitation.} $\vdash A$ implies $\vdash \Box A$.
  \item \textbf{L\"ob's axiom.} $\vdash \Box(\Box A \to A) \to \Box A$.
\end{enumerate}
The resulting system is \emph{G\"odel--L\"ob logic} $\GL$. Its Kripke semantics is exceptionally
clean: $\GL$ is sound and complete for the frames whose accessibility relation is transitive and
converse well-founded, i.e.\ admits no infinite ascending chain
$w_0 \mathrel{R} w_1 \mathrel{R} \cdots$. On a finite carrier, transitivity together with converse
well-foundedness is equivalent to transitivity together with irreflexivity.

\subsection{Adding a temporal dimension}

A provability predicate is attached to a \emph{fixed} theory. When the theory grows one wants a
second modality tracking time; we write $\blacksquare A$ for ``$A$ holds now and at every future
moment'', interpreted along a preorder $T$. The interesting content lies in how the operators
interact. We impose
\[
  w \mathrel{T} w' \ \text{and}\ w' \mathrel{R} v \implies w \mathrel{R} v ,
\]
read as: \emph{the provability horizon does not widen with time}. Its syntactic counterpart is
the axiom $\Box A \to \blacksquare\Box A$: \textbf{what is provable now remains provable forever}.
This axiom is the pivot on which both halves of the main proof turn.

\subsection{The problem and the result}

For a modal logic, the \emph{finite model property} asserts that every non-theorem is refuted in
some finite model. An \emph{explicitly bounded} finite model property additionally names a
computable function $f$ such that a countermodel with at most $f(A)$ worlds always exists; this is
what converts semantic search into an algorithm. Let $\sub(A)$ denote the number of distinct
subformulas of $A$, including $A$ itself.

\begin{theorem}[Main Theorem]\label{thm:intro-main}
If $A$ is not derivable in $\TGL$, then there is a temporal G\"odel--L\"ob model $N$ with a finite
world set, $|N| \le 2^{\sub(A)}$, and a world $v$ of $N$ at which $A$ fails. In particular
$|N| \le 2^{2\sub(A)}$.
\end{theorem}

Two obstacles stand in the way, and both are genuine.

\medskip
\noindent\textbf{Obstacle 1 (filtration and compatibility).} The standard method for bounding
countermodel size is filtration through the subformulas of $A$. For $\GL$ this is classical, using
Segerberg's strictness clause. But the \emph{naive} filtration of the temporal relation does
\emph{not} preserve the compatibility condition. The repair is to strengthen the filtered temporal
relation with a $\Box$-persistence clause; this is sound precisely because compatibility holds
upstream. This was the only genuine definitional obstruction encountered.

\medskip
\noindent\textbf{Obstacle 2 (no infinite canonical model).} Filtration shrinks an \emph{existing}
countermodel. To pass from ``not derivable'' to ``has a countermodel'' one needs completeness, and
the standard canonical model of maximal consistent sets is illegal for $\GL$: its accessibility
relation is not converse well-founded. We therefore build a \emph{finite canonical model over the
subformula closure of a single formula}, using the \emph{same} filtration relations.

\section{The system \texorpdfstring{$\TGL$}{TGL}}

\subsection{Syntax}

\begin{definition}[Formulas]
Formulas are generated by
$A ::= p_n \mid \bot \mid (A \to A) \mid \Box A \mid \blacksquare A$, $n \in \mathbb{N}$.
We abbreviate $\lnot A := A \to \bot$, $A \wedge B := \lnot(A \to \lnot B)$ and
$A \vee B := \lnot A \to B$.
\end{definition}

\begin{definition}[Subformulas]
$\Sub(A)$ is defined by recursion:
$\Sub(p) = \{p\}$, $\Sub(\bot) = \{\bot\}$,
$\Sub(B \to C) = \{B \to C\} \cup \Sub(B) \cup \Sub(C)$,
$\Sub(\Box B) = \{\Box B\} \cup \Sub(B)$, and
$\Sub(\blacksquare B) = \{\blacksquare B\} \cup \Sub(B)$.
Put $\sub(A) := |\Sub(A)|$.
\end{definition}

\begin{lemma}\label{lem:sub}
$A \in \Sub(A)$; if $B \in \Sub(A)$ then $\Sub(B) \subseteq \Sub(A)$; and
$1 \le \sub(A) \le |A|$, where $|A|$ is the number of nodes of the syntax tree.
\end{lemma}

\begin{proof}
Induction on $A$. The middle claim yields the three facts used constantly below: from
$(B \to C) \in \Sub(A)$ infer $B, C \in \Sub(A)$; from $\Box B \in \Sub(A)$ infer $B \in \Sub(A)$;
from $\blacksquare B \in \Sub(A)$ infer $B \in \Sub(A)$. The size bound follows from
$|X \cup Y| \le |X| + |Y|$ and $|\{a\} \cup X| \le |X| + 1$.
\end{proof}

Because $\sub(A) \le |A|$, every bound stated with $\sub$ also holds with syntactic size.

\subsection{Frames and models}

\begin{definition}[Temporal G\"odel--L\"ob frame]\label{def:frame}
A \emph{temporal G\"odel--L\"ob frame} is a triple $F = (W, R, T)$ with $R, T \subseteq W \times W$
satisfying:
\begin{itemize}
  \item[\textbf{(R-trans)}] $R$ is transitive;
  \item[\textbf{(R-wf)}] $R$ is converse well-founded: there is no infinite chain
        $w_0 \mathrel{R} w_1 \mathrel{R} \cdots$; equivalently every non-empty subset of $W$ has an
        $R$-maximal element;
  \item[\textbf{(T-refl)}] $T$ is reflexive;
  \item[\textbf{(T-trans)}] $T$ is transitive;
  \item[\textbf{(compat)}] $w \mathrel{T} w'$ and $w' \mathrel{R} v$ imply $w \mathrel{R} v$.
\end{itemize}
A \emph{model} $M = (F, V)$ adds a valuation $V : \mathbb{N} \to \mathcal{P}(W)$.
\end{definition}

\begin{definition}[Satisfaction]
$M, w \Forces p$ iff $w \in V(p)$; $M, w \nVdash \bot$;
$M, w \Forces B \to C$ iff ($M,w \Forces B$ implies $M, w \Forces C$);
$M, w \Forces \Box B$ iff $M, v \Forces B$ for all $v$ with $w \mathrel{R} v$;
$M, w \Forces \blacksquare B$ iff $M, v \Forces B$ for all $v$ with $w \mathrel{T} v$.
$A$ is \emph{valid}, written $\models A$, when $M, w \Forces A$ for every model and world.
\end{definition}

Observe that (R-wf) forbids $w \mathrel{R} w$, so on a finite carrier (R-trans) and (R-wf) say
exactly that $R$ is a strict partial order.

\subsection{Propositional tautologies of the object language}

\begin{definition}\label{def:taut}
For $v$ assigning truth values to formulas, define $\ev_v$ by treating atoms and \emph{every}
formula of the shape $\Box B$ or $\blacksquare B$ as an unanalysed propositional letter:
$\ev_v(p) = v(p)$, $\ev_v(\bot) = 0$, $\ev_v(B \to C) = \ev_v(B) \Rightarrow \ev_v(C)$,
$\ev_v(\Box B) = v(\Box B)$, $\ev_v(\blacksquare B) = v(\blacksquare B)$.
Call $A$ a \emph{tautology} if $\ev_v(A) = 1$ for all $v$.
\end{definition}

\begin{lemma}\label{lem:taut}
For every model $M$ and world $w$ we have $M, w \Forces A$ iff $\ev_{v_w}(A) = 1$, where
$v_w(B) := [\,M, w \Forces B\,]$. Consequently every tautology is valid.
\end{lemma}

\begin{proof}
Induction on $A$; the modal cases are definitional identities.
\end{proof}

\subsection{The calculus}

\begin{definition}[$\TGL$]\label{def:calculus}
$\vdash A$ is generated by:
\begin{center}
\begin{tabular}{ll}
\toprule
\textbf{Taut} & every propositional tautology in the sense of Definition~\ref{def:taut}\\
\textbf{MP} & from $\vdash A \to B$ and $\vdash A$ infer $\vdash B$\\
$\mathbf{K}_\Box$ & $\vdash \Box(A \to B) \to (\Box A \to \Box B)$\\
\textbf{L\"ob} & $\vdash \Box(\Box A \to A) \to \Box A$\\
$\mathbf{K}_\blacksquare$ & $\vdash \blacksquare(A \to B) \to (\blacksquare A \to \blacksquare B)$\\
$\mathbf{T}_\blacksquare$ & $\vdash \blacksquare A \to A$\\
$\mathbf{4}_\blacksquare$ & $\vdash \blacksquare A \to \blacksquare\blacksquare A$\\
\textbf{Int} & $\vdash \Box A \to \blacksquare\Box A$\\
$\mathbf{Nec}_\Box$ & from $\vdash A$ infer $\vdash \Box A$\\
$\mathbf{Nec}_\blacksquare$ & from $\vdash A$ infer $\vdash \blacksquare A$\\
\bottomrule
\end{tabular}
\end{center}
No transitivity axiom for $\Box$ is postulated.
\end{definition}

\begin{theorem}[Soundness]\label{thm:soundness}
If $\vdash A$ then $\models A$.
\end{theorem}

\begin{proof}
Induction on the derivation. \textbf{Taut} is Lemma~\ref{lem:taut}; \textbf{MP} is immediate;
$\mathbf{K}_\Box$ and $\mathbf{K}_\blacksquare$ are pointwise; $\mathbf{T}_\blacksquare$ uses
(T-refl) and $\mathbf{4}_\blacksquare$ uses (T-trans). For \textbf{Int}: if $M, w \Forces \Box A$,
$w \mathrel{T} w'$ and $w' \mathrel{R} v$, then $w \mathrel{R} v$ by (compat), so
$M, v \Forces A$; hence $M, w' \Forces \Box A$, whence $M, w \Forces \blacksquare\Box A$. Both
necessitation rules are immediate.

For \textbf{L\"ob}, suppose $M, w \Forces \Box(\Box A \to A)$ but $M, w \nVdash \Box A$. The set
$X = \{v : w \mathrel{R} v,\ M, v \nVdash A\}$ is non-empty, so by (R-wf) it has an $R$-maximal
element $m$. If $m \mathrel{R} y$ then $w \mathrel{R} y$ by (R-trans), and maximality forces
$M, y \Forces A$; hence $M, m \Forces \Box A$. Since $w \mathrel{R} m$, we get
$M, m \Forces \Box A \to A$ and therefore $M, m \Forces A$, contradicting $m \in X$.
\end{proof}

\begin{corollary}[Consistency and non-triviality]\label{cor:consistent}
Let $P$ be the one-world frame with $R = \emptyset$ and $T$ the identity, with the atom-empty
valuation. Then $P$ is a temporal G\"odel--L\"ob frame, and $\nvdash \bot$ and $\nvdash p$ for
every atom $p$.
\end{corollary}

\subsection{Derivations from hypothesis lists}

For a finite list $\Gamma = [x_1,\dots,x_n]$ put
$\Gamma \Rightarrow X := x_1 \to (\cdots \to (x_n \to X))$ and define $\Gamma \vdash X$ to mean
$\vdash (\Gamma \Rightarrow X)$.

\begin{lemma}[Propositional interface]\label{lem:interface}
Because \emph{all} tautologies are axioms, the following hold, each by one application of
\textbf{Taut} and \textbf{MP} after unwinding the fold:
\begin{enumerate}
  \item (tautological consequence) if for all $v$, $\ev_v(x)=1$ for all $x \in \Gamma$ implies
        $\ev_v(X)=1$, then $\Gamma \vdash X$;
  \item (assumption) $x \in \Gamma$ implies $\Gamma \vdash x$;
  \item (weakening) $\Gamma_1 \subseteq \Gamma_2$ and $\Gamma_1 \vdash X$ imply $\Gamma_2 \vdash X$;
  \item (modus ponens) $\Gamma \vdash X \to Y$ and $\Gamma \vdash X$ imply $\Gamma \vdash Y$;
  \item (cut) if $\Gamma \vdash x$ for every $x \in \Delta$ and $\Delta \vdash X$, then
        $\Gamma \vdash X$;
  \item (case analysis) $B :: \Gamma \vdash X$ and $\lnot B :: \Gamma \vdash X$ imply
        $\Gamma \vdash X$.
\end{enumerate}
\end{lemma}

\begin{lemma}[Modal distribution over lists]\label{lem:distrib}
For every list $\Delta$ and formula $X$,
\[
  \vdash \Box(\Delta \Rightarrow X) \to (\Box\Delta \Rightarrow \Box X),
  \qquad
  \vdash \blacksquare(\Delta \Rightarrow X) \to (\blacksquare\Delta \Rightarrow \blacksquare X),
\]
where $\Box\Delta$ is $\Delta$ with $\Box$ prefixed to each member. Consequently
$\Delta \vdash X$ implies $\Box\Delta \vdash \Box X$, and likewise for $\blacksquare$.
\end{lemma}

\begin{proof}
Induction on $\Delta$, the step being one application of $\mathbf{K}$ composed inside the
implication; the consequences follow by \textbf{Nec} and \textbf{MP}.
\end{proof}

\begin{definition}
$\Gamma$ is \emph{consistent} if $\Gamma \nvdash \bot$.
\end{definition}

\begin{lemma}[Finite Lindenbaum]\label{lem:lindenbaum-list}
For every finite list $L$ and consistent $\Gamma$ there is a consistent $\Gamma' \supseteq \Gamma$
such that for every $B \in L$, either $B \in \Gamma'$ or $\lnot B \in \Gamma'$.
\end{lemma}

\begin{proof}
Induction on $L$. At the step $B :: L$: if $B :: \Gamma$ is inconsistent then $\lnot B :: \Gamma$
is consistent by case analysis (Lemma~\ref{lem:interface}), and we recurse on that; otherwise we
recurse on $B :: \Gamma$.
\end{proof}

\section{Filtration}

Throughout this section fix a finite set $\Cl$ of formulas; in the application $\Cl = \Sub(A)$.

\subsection{The two filtered relations}

\begin{definition}\label{def:filt}
For $S, S' \subseteq \Cl$ define $S \mathrel{\Rcl} S'$ to hold iff
\[
  \underbrace{\forall B\,\big(\Box B \in \Cl \wedge \Box B \in S \Rightarrow
     B \in S' \wedge \Box B \in S'\big)}_{\textbf{(forth)}}
  \ \wedge\
  \underbrace{\exists B\,\big(\Box B \in \Cl \wedge \Box B \in S' \wedge \Box B \notin S\big)}_{\textbf{(strict)}}
\]
and $S \mathrel{\Tcl} S'$ to hold iff
\[
  \underbrace{\forall B\,\big(\blacksquare B \in \Cl \wedge \blacksquare B \in S \Rightarrow
     B \in S' \wedge \blacksquare B \in S'\big)}_{\textbf{(forth)}}
  \ \wedge\
  \underbrace{\forall B\,\big(\Box B \in \Cl \wedge \Box B \in S \Rightarrow \Box B \in S'\big)}_{\textbf{($\Box$-persistence)}} .
\]
\end{definition}

The clause \textbf{(strict)} is Segerberg's device; it will yield converse well-foundedness. The
clause \textbf{($\Box$-persistence)} is the repair for Obstacle~1.

\begin{lemma}\label{lem:filt-trans}
$\Rcl$ and $\Tcl$ are transitive.
\end{lemma}

\begin{proof}
For $\Rcl$: (forth) composes because it delivers not only $B$ but also $\Box B$ at the successor;
(strict) is inherited from the \emph{first} step, whose witness $\Box B$ is carried forward by
(forth) of the second step. For $\Tcl$ both clauses compose in the same way.
\end{proof}

\begin{lemma}[Compatibility survives]\label{lem:compat}
If $S \mathrel{\Tcl} S_1$ and $S_1 \mathrel{\Rcl} S_2$, then $S \mathrel{\Rcl} S_2$.
\end{lemma}

\begin{proof}
(forth): if $\Box B \in \Cl \cap S$ then $\Box B \in S_1$ by ($\Box$-persistence), whence
$B, \Box B \in S_2$ by (forth) of $\Rcl$. (strict): take the witness $\Box B \in S_2 \setminus S_1$
supplied by $S_1 \mathrel{\Rcl} S_2$; then $\Box B \notin S$, for otherwise ($\Box$-persistence)
would place $\Box B$ in $S_1$.
\end{proof}

This is where the extra clause pays for itself: without it the argument breaks in both parts, and
compatibility genuinely fails on the quotient.

\subsection{The counting measure}

\begin{definition}
Let $\mathrm{Box}(\Cl) := \{C \in \Cl : C \text{ has the form } \Box D\}$ and, for
$S \subseteq \Cl$, let $\beta(S) := |\{C \in \mathrm{Box}(\Cl) : C \in S\}| \le |\mathrm{Box}(\Cl)|$.
\end{definition}

\begin{theorem}[Strict growth]\label{thm:strict}
If $S \mathrel{\Rcl} S'$ then $\beta(S) < \beta(S')$.
\end{theorem}

\begin{proof}
By (forth) every $\Box D \in \mathrm{Box}(\Cl)$ lying in $S$ also lies in $S'$, so the counted set
for $S$ is a subset of that for $S'$. By (strict) there is $\Box B \in \mathrm{Box}(\Cl)$ in $S'$
but not $S$, so the inclusion is proper and cardinality strictly increases.
\end{proof}

\begin{corollary}[Converse well-foundedness by counting]\label{cor:wf}
For any type $\alpha$ and any map $f : \alpha \to \mathcal{P}(\Cl)$, the relation
$a \prec b :\iff f(b) \mathrel{\Rcl} f(a)$ is well-founded.
\end{corollary}

\begin{proof}
$a \prec b$ implies $|\mathrm{Box}(\Cl)| - \beta(f(a)) < |\mathrm{Box}(\Cl)| - \beta(f(b))$ by
Theorem~\ref{thm:strict} and $\beta \le |\mathrm{Box}(\Cl)|$, so $\prec$ embeds into $<$ on
$\mathbb{N}$.
\end{proof}

Corollary~\ref{cor:wf} is the combinatorial heart of the development. Any structure whose
accessibility relation is pulled back from $\Rcl$ automatically validates L\"ob's axiom, and its
\emph{depth} is bounded by $|\mathrm{Box}(\Cl)|$: no $R$-chain has more than $|\mathrm{Box}(\Cl)|$
steps.

\subsection{The filtered model}

Fix a model $M$ and a formula $A$; put $\Cl := \Sub(A)$.

\begin{definition}
For $u \in W$ let the \emph{subformula theory} be $\theta(u) := \{B \in \Sub(A) : M, u \Forces B\}$.
Let $W^\ast := \{\theta(u) : u \in W\}$ and put $F^\ast := (W^\ast, \Rcl, \Tcl)$ with
$V^\ast(p) := \{S \in W^\ast : p \in S\}$.
\end{definition}

\begin{theorem}\label{thm:filt-frame}
$F^\ast$ is a temporal G\"odel--L\"ob frame.
\end{theorem}

\begin{proof}
(R-trans) and (T-trans) are Lemma~\ref{lem:filt-trans}; (compat) is Lemma~\ref{lem:compat};
(R-wf) is Corollary~\ref{cor:wf} applied to $W^\ast \hookrightarrow \mathcal{P}(\Cl)$. For
(T-refl), let $S = \theta(u)$: if $\blacksquare B \in \Sub(A) \cap S$ then $M, u \Forces \blacksquare B$,
so $M, u \Forces B$ by (T-refl) upstream, and $B \in \Sub(A)$ by Lemma~\ref{lem:sub}, so $B \in S$;
($\Box$-persistence) is trivial for $S' = S$.
\end{proof}

\begin{theorem}[Filtration lemma]\label{thm:filt-truth}
For every $B \in \Sub(A)$ and every $u \in W$,
\[
  F^\ast, V^\ast, \theta(u) \Forces B \iff M, u \Forces B .
\]
\end{theorem}

\begin{proof}
Induction on $B$.

\emph{Atoms:} $\theta(u) \in V^\ast(p)$ iff $p \in \theta(u)$ iff $M, u \Forces p$.
\emph{Falsity:} both sides false. \emph{Implication:} immediate from the induction hypotheses at
the two immediate subformulas, which lie in $\Sub(A)$ by Lemma~\ref{lem:sub}.

\emph{Box, $\Leftarrow$:} assume $M, u \Forces \Box B$, so $\Box B \in \theta(u)$. Let
$\theta(u) \mathrel{\Rcl} S'$ and choose $v$ with $S' = \theta(v)$; by (forth), $B \in \theta(v)$,
i.e.\ $M, v \Forces B$, and the induction hypothesis applies.

\emph{Box, $\Rightarrow$:} assume $\theta(u) \Forces \Box B$ in the quotient but
$M, u \nVdash \Box B$. Then $X := \{x : u \mathrel{R} x,\ M, x \nVdash B\} \ne \emptyset$; by (R-wf)
upstream choose $m$ $R$-maximal in $X$. Maximality and (R-trans) give $M, m \Forces \Box B$. We
claim $\theta(u) \mathrel{\Rcl} \theta(m)$. For (forth): if $\Box D \in \Sub(A) \cap \theta(u)$
then $M, u \Forces \Box D$; since $u \mathrel{R} m$, $M, m \Forces D$; and if $m \mathrel{R} y$
then $u \mathrel{R} y$ by transitivity, so $M, m \Forces \Box D$. For (strict): $\Box B \in \theta(m)$
while $\Box B \notin \theta(u)$. Hence $\theta(m) \Forces B$ in the quotient, so $M, m \Forces B$
by induction hypothesis, contradicting $m \in X$.

\emph{Temporal box, $\Leftarrow$:} as above, using (forth) of $\Tcl$.

\emph{Temporal box, $\Rightarrow$:} assume $\theta(u) \Forces \blacksquare B$ but
$M, u \nVdash \blacksquare B$; pick $x$ with $u \mathrel{T} x$ and $M, x \nVdash B$. We check
$\theta(u) \mathrel{\Tcl} \theta(x)$. (forth): if $\blacksquare D \in \Sub(A) \cap \theta(u)$ then
$M, x \Forces D$ since $u \mathrel{T} x$, and $M, x \Forces \blacksquare D$ by (T-trans).
($\Box$-persistence): if $\Box D \in \Sub(A) \cap \theta(u)$ and $x \mathrel{R} y$, then
$u \mathrel{R} y$ by \textbf{(compat)}, so $M, y \Forces D$; hence $M, x \Forces \Box D$. Therefore
$\theta(x) \Forces B$ in the quotient, so $M, x \Forces B$ --- contradiction.
\end{proof}

Note where each frame condition is spent: (R-wf) upstream in the $\Box$ case, (T-trans) and
\textbf{(compat)} upstream in the $\blacksquare$ case. The clause ($\Box$-persistence) is
\emph{available} precisely because (compat) holds in $M$.

\begin{theorem}[Small model property]\label{thm:small}
If $M, w \nVdash A$ then there is a temporal G\"odel--L\"ob model $N$ with $|N| \le 2^{\sub(A)}$
and a world $v$ with $N, v \nVdash A$.
\end{theorem}

\begin{proof}
Take $N = (F^\ast, V^\ast)$ and $v = \theta(w)$. Since $W^\ast \subseteq \mathcal{P}(\Sub(A))$ we
have $|W^\ast| \le 2^{\sub(A)}$, and $A \in \Sub(A)$, so Theorem~\ref{thm:filt-truth} transfers the
failure.
\end{proof}

\begin{corollary}[Bounded semantic test]\label{cor:bounded-test}
$\models A$ if and only if $A$ holds at every world of every temporal G\"odel--L\"ob model with at
most $2^{2\sub(A)}$ worlds.
\end{corollary}

Corollary~\ref{cor:bounded-test} already justifies reading a \emph{successful} exhaustive bounded
search as a proof of validity. What it does not give is that a \emph{non-derivable} formula must
have a small countermodel; for that we need completeness.

\section{Completeness via a finite canonical model}

\subsection{Why the usual canonical model fails}

The classical route builds a model whose worlds are all maximal consistent sets, with
$\Gamma \mathrel{R} \Delta$ iff $\{B, \Box B : \Box B \in \Gamma\} \subseteq \Delta$. For $\GL$ this
relation is transitive but \emph{not} converse well-founded, so the canonical frame is not in the
frame class. We work over a finite closure instead, reusing the relations of the previous section,
so that Corollary~\ref{cor:wf} hands us (R-wf) for free.

\subsection{Closures, decided subsets, worlds}

\begin{definition}
A finite set $\Cl$ of formulas is \emph{closed} if $(B \to C) \in \Cl$ implies $B, C \in \Cl$;
$\Box B \in \Cl$ implies $B \in \Cl$; and $\blacksquare B \in \Cl$ implies $B \in \Cl$.
\end{definition}

\begin{lemma}
$\Sub(A)$ is closed. \emph{(Lemma~\ref{lem:sub}.)}
\end{lemma}

\begin{definition}
For $t \subseteq \Cl$ let $\gamma(t)$ be the list obtained from an enumeration of $\Cl$ by mapping
$B \mapsto B$ if $B \in t$ and $B \mapsto \lnot B$ otherwise. Say $t$ is a \emph{world of $\Cl$}
when $\gamma(t)$ is consistent, and write $\Wcan(\Cl)$ for the finite set of worlds.
\end{definition}

\begin{lemma}[Closure under derivation inside $\Cl$]\label{lem:memder}
If $t \in \Wcan(\Cl)$, $B \in \Cl$ and $\gamma(t) \vdash B$, then $B \in t$.
\end{lemma}

\begin{proof}
If $B \notin t$ then $\lnot B \in \gamma(t)$, so $\gamma(t) \vdash \bot$, contradicting
consistency.
\end{proof}

\begin{lemma}[Lindenbaum for a finite closure]\label{lem:lindenbaum}
If $\Gamma$ is consistent then there is $t \in \Wcan(\Cl)$ with $x \in t$ for every
$x \in \Gamma \cap \Cl$, and $B \notin t$ whenever $\lnot B \in \Gamma$.
\end{lemma}

\begin{proof}
Apply Lemma~\ref{lem:lindenbaum-list} with $L$ an enumeration of $\Cl$, obtaining a consistent
$\Gamma' \supseteq \Gamma$ deciding every member of $\Cl$; put $t := \{B \in \Cl : B \in \Gamma'\}$.
Every member of $\gamma(t)$ belongs to $\Gamma'$ --- positively by construction, negatively because
$\Gamma'$ decides $\Cl$ --- so weakening shows $\gamma(t)$ consistent. The stated properties are
immediate, the second because a consistent list cannot contain both $B$ and $\lnot B$.
\end{proof}

Since worlds are subsets of $\Cl$, $|\Wcan(\Cl)| \le 2^{|\Cl|}$; this is where the final bound
comes from.

\subsection{The two existence lemmas}

Fix a closed $\Cl$ and $t \in \Wcan(\Cl)$.

\begin{theorem}[Existence lemma for $\Box$: the L\"ob argument]\label{thm:box-exists}
If $\Box B \in \Cl$ and $\Box B \notin t$, then there is $s \in \Wcan(\Cl)$ with
$t \mathrel{\Rcl} s$ and $B \notin s$.
\end{theorem}

\begin{proof}
Let $D_0 := [\Box D : \Box D \in \Cl \cap t]$, and set
\[
  D_1 := [D : \Box D \in D_0] \frown D_0, \qquad D_2 := D_1 \frown [\Box B,\ \lnot B].
\]

\emph{Claim: $D_2$ is consistent.} Suppose $D_2 \vdash \bot$. Tautological reasoning
(Lemma~\ref{lem:interface}) converts this into $D_1 \vdash \Box B \to B$. Apply $\Box$-distribution
over lists (Lemma~\ref{lem:distrib}) to get $\Box D_1 \vdash \Box(\Box B \to B)$, and then
\textbf{L\"ob's axiom} with modus ponens to get $\Box D_1 \vdash \Box B$. Now every member of
$\Box D_1$ is derivable from $\gamma(t)$:
\begin{itemize}
  \item the first half of $D_1$ consists of the un-boxed $D$'s, so boxing yields $\Box D$ with
        $\Box D \in \Cl \cap t$: literally an assumption of $\gamma(t)$;
  \item the second half of $D_1$ is $D_0$ itself, so boxing yields $\Box\Box D$: here we use the
        \emph{derived transitivity} $\vdash \Box D \to \Box\Box D$
        (Theorem~\ref{thm:four}) applied to the assumption $\Box D$.
\end{itemize}
By cut, $\gamma(t) \vdash \Box B$, so $\Box B \in t$ by Lemma~\ref{lem:memder} --- contradiction.

By Lemma~\ref{lem:lindenbaum} there is $s \in \Wcan(\Cl)$ containing every member of
$D_2 \cap \Cl$ and omitting $B$. Then (forth) holds: if $\Box E \in \Cl \cap t$ then both $\Box E$
and $E$ occur in $D_2$ and both lie in $\Cl$ (using closedness for $E$), hence both lie in $s$. And
(strict) holds: $\Box B \in D_2 \cap \Cl$ so $\Box B \in s$, while $\Box B \notin t$.
\end{proof}

L\"ob's axiom, which makes the \emph{infinite} canonical model illegal, is precisely the tool that
makes the \emph{finite} one work: it licenses adding $\Box B$ itself to the successor's hypothesis
list, which is what supplies the (strict) clause.

\begin{theorem}[Existence lemma for $\blacksquare$]\label{thm:glob-exists}
If $\blacksquare B \in \Cl$ and $\blacksquare B \notin t$, then there is $s \in \Wcan(\Cl)$ with
$t \mathrel{\Tcl} s$ and $B \notin s$.
\end{theorem}

\begin{proof}
Let $G_0 := [\blacksquare D : \blacksquare D \in \Cl \cap t]$ and
$B_0 := [\Box D : \Box D \in \Cl \cap t]$, and set
\[
  D_1 := [D : \blacksquare D \in G_0] \frown G_0 \frown B_0, \qquad D_2 := D_1 \frown [\lnot B].
\]
\emph{Claim: $D_2$ is consistent.} If $D_2 \vdash \bot$ then tautologically $D_1 \vdash B$, hence
$\blacksquare D_1 \vdash \blacksquare B$ by Lemma~\ref{lem:distrib}. Each member of
$\blacksquare D_1$ is derivable from $\gamma(t)$: $\blacksquare D$ with
$\blacksquare D \in \Cl \cap t$ is an assumption; $\blacksquare\blacksquare D$ follows from
$\mathbf{4}_\blacksquare$; and $\blacksquare\Box D$ follows from the \textbf{interaction axiom}
$\Box D \to \blacksquare\Box D$. By cut, $\gamma(t) \vdash \blacksquare B$, so
$\blacksquare B \in t$ by Lemma~\ref{lem:memder} --- contradiction.

By Lemma~\ref{lem:lindenbaum} pick $s \in \Wcan(\Cl)$ containing $D_2 \cap \Cl$ and omitting $B$.
Then (forth) of $\Tcl$ holds because $D_2$ contains both $\blacksquare E$ and $E$ for each
$\blacksquare E \in \Cl \cap t$; and ($\Box$-persistence) holds because $D_2$ contains $B_0$.
\end{proof}

The three fuels used here --- $\blacksquare$-necessitation, $\mathbf{4}_\blacksquare$ and
\textbf{Int} --- correspond exactly to the three demands made by $\Tcl$: transmit $E$, transmit
$\blacksquare E$, transmit $\Box E$.

\subsection{The finite canonical model}

\begin{definition}
For closed $\Cl$ let $F^{\mathrm{can}} := (\Wcan(\Cl), \Rcl, \Tcl)$ with
$V^{\mathrm{can}}(p) := \{t : p \in t\}$.
\end{definition}

\begin{theorem}\label{thm:can-frame}
$F^{\mathrm{can}}$ is a temporal G\"odel--L\"ob frame.
\end{theorem}

\begin{proof}
Transitivity of both relations is Lemma~\ref{lem:filt-trans}; (compat) is Lemma~\ref{lem:compat};
(R-wf) is Corollary~\ref{cor:wf}. For (T-refl), check $t \mathrel{\Tcl} t$: ($\Box$-persistence) is
trivial, and for (forth), if $\blacksquare E \in \Cl \cap t$ then $\gamma(t) \vdash E$ by
$\mathbf{T}_\blacksquare$, so $E \in t$ by Lemma~\ref{lem:memder}.
\end{proof}

(T-refl) is the only frame condition here needing a syntactic argument; everything else is
inherited from the abstract properties of $\Rcl$ and $\Tcl$.

\begin{theorem}[Truth lemma]\label{thm:can-truth}
For every $B \in \Cl$ and $t \in \Wcan(\Cl)$: $F^{\mathrm{can}}, V^{\mathrm{can}}, t \Forces B$ iff
$B \in t$.
\end{theorem}

\begin{proof}
Induction on $B$. \emph{Atoms:} by definition. \emph{Falsity:} $\bot \notin t$, since $\bot \in t$
would destroy consistency of $\gamma(t)$.

\emph{Implication $B \to C$ (with $B, C \in \Cl$ by closedness):} ($\Rightarrow$) Suppose
$t \Forces B \to C$. If $B \in t$ then $t \Forces B$, so $t \Forces C$, so $C \in t$, and
$\gamma(t) \vdash B \to C$ tautologically from $C$. If $B \notin t$ then $\lnot B \in \gamma(t)$
and $\gamma(t) \vdash B \to C$ tautologically. Either way Lemma~\ref{lem:memder} applies.
($\Leftarrow$) If $B \to C \in t$ and $t \Forces B$ then $B \in t$, so $\gamma(t) \vdash C$ by
modus ponens on assumptions, so $C \in t$ and $t \Forces C$.

\emph{$\Box B$:} ($\Leftarrow$) if $\Box B \in t$ and $t \mathrel{\Rcl} s$ then $B \in s$ by
(forth), so $s \Forces B$. ($\Rightarrow$) contrapositive: if $\Box B \notin t$,
Theorem~\ref{thm:box-exists} supplies $s$ with $t \mathrel{\Rcl} s$ and $B \notin s$, so
$s \nVdash B$ and $t \nVdash \Box B$.

\emph{$\blacksquare B$:} identical, using Theorem~\ref{thm:glob-exists}.
\end{proof}

\begin{theorem}[Weak completeness]\label{thm:completeness}
If $\models A$ then $\vdash A$.
\end{theorem}

\begin{proof}
Suppose $\nvdash A$. Then $[\lnot A]$ is consistent: if $\vdash \lnot A \to \bot$ then $\vdash A$
by the tautology $(\lnot A \to \bot) \to A$. Apply Lemma~\ref{lem:lindenbaum} with
$\Cl = \Sub(A)$ to get $t \in \Wcan(\Sub(A))$ with $A \notin t$. By Theorem~\ref{thm:can-truth},
$t \nVdash A$ in the finite canonical model, legal by Theorem~\ref{thm:can-frame}. Hence
$\nvDash A$.
\end{proof}

\begin{corollary}\label{cor:iff}
$\vdash A$ if and only if $\models A$.
\end{corollary}

\section{The main theorem}

\begin{theorem}[Finite model property, sharp form]\label{thm:fmp-sharp}
If $\nvdash A$ then there is a temporal G\"odel--L\"ob model $N$ with finite world set,
$|N| \le 2^{\sub(A)}$, and a world $v$ with $N, v \nVdash A$.
\end{theorem}

\begin{proof}
As in Theorem~\ref{thm:completeness} obtain $t \in \Wcan(\Sub(A))$ with $A \notin t$; by
Theorem~\ref{thm:can-truth} the finite canonical model over $\Sub(A)$ refutes $A$ at $t$. Its
worlds are subsets of $\Sub(A)$, so there are at most $2^{\sub(A)}$ of them.
\end{proof}

\begin{theorem}[The bound as conjectured]\label{thm:fmp}
If $\nvdash A$ then $A$ has a temporal G\"odel--L\"ob countermodel with at most $2^{2\sub(A)}$
worlds.
\end{theorem}

\begin{theorem}[Decision procedure]\label{thm:decide}
$\vdash A$ if and only if $A$ holds at every world of every temporal G\"odel--L\"ob model with at
most $2^{2\sub(A)}$ worlds.
\end{theorem}

\begin{proof}
Combine Corollary~\ref{cor:iff} with Corollary~\ref{cor:bounded-test}.
\end{proof}

Since for a fixed finite carrier there are only finitely many pairs of relations and finitely many
valuations of the atoms of $A$, the right-hand side is a finite, mechanically checkable condition.

\begin{corollary}
Derivability in $\TGL$ is decidable.
\end{corollary}

\begin{theorem}[One-sided soundness of search]
If $A$ has \emph{no} countermodel with at most $2^{2\sub(A)}$ worlds then $\models A$; and if $A$
fails at some world of some model whatsoever, then $\nvdash A$ and $A$ already fails in a model of
at most $2^{2\sub(A)}$ worlds.
\end{theorem}

The two directions have different logical costs: ``no countermodel $\Rightarrow$ valid'' is pure
filtration and needs no completeness, while ``$\nvdash A \Rightarrow$ small countermodel'' is
exactly where completeness enters.

\section{Structural corollaries and non-degeneracy}

\begin{theorem}[Transitivity from L\"ob]\label{thm:four}
$\vdash \Box A \to \Box\Box A$, with no transitivity axiom assumed.
\end{theorem}

\begin{proof}
Put $C := A \wedge \Box A$. Both $C \to \Box A$ and $C \to A$ are tautologies in the sense of
Definition~\ref{def:taut}, hence theorems; boxing them via $\mathbf{Nec}_\Box$ and
$\mathbf{K}_\Box$ gives $\vdash \Box C \to \Box\Box A$ and $\vdash \Box C \to \Box A$. From the
second, propositional reasoning yields $\vdash A \to (\Box C \to C)$: if $A$ and $\Box C$ hold then
$\Box A$ holds by the second theorem, so $A \wedge \Box A = C$ holds. Boxing this gives
$\vdash \Box A \to \Box(\Box C \to C)$, and \textbf{L\"ob} turns the consequent into $\Box C$, so
$\vdash \Box A \to \Box C$. Chaining with $\vdash \Box C \to \Box\Box A$ finishes.
\end{proof}

\begin{theorem}[L\"ob's rule]
If $\vdash \Box A \to A$ then $\vdash A$.
\end{theorem}

\begin{proof}
Necessitation gives $\vdash \Box(\Box A \to A)$, L\"ob's axiom gives $\vdash \Box A$, and modus
ponens on the hypothesis gives $\vdash A$.
\end{proof}

\begin{theorem}[G\"odel's second incompleteness theorem, object-language form]
$\nvdash \Box\bot \to \bot$.
\end{theorem}

\begin{proof}
Take the one-world frame of Corollary~\ref{cor:consistent}, with $R = \emptyset$ and $T$ the
identity. Then $\Box\bot$ holds vacuously and $\bot$ does not; soundness
(Theorem~\ref{thm:soundness}) finishes.
\end{proof}

\begin{corollary}
The consistency statement therefore possesses a countermodel of at most $2^{2 \cdot 3} = 64$
worlds; in fact one world suffices.
\end{corollary}

\begin{theorem}[The modalities do not collapse]
$\nvdash \blacksquare p \to \Box p$ and $\nvdash \Box p \to \blacksquare p$.
\end{theorem}

\begin{proof}
For the first, take $W = \{0,1\}$ with $R = \{(1,0)\}$ and $T$ the identity. All frame conditions
hold: $R$ is transitive and irreflexive, $T$ is a preorder, and (compat) holds since
$w \mathrel{T} w'$ forces $w = w'$. Let $p$ be true exactly at $1$; then $\blacksquare p$ holds at
$1$ but $\Box p$ fails there because $1 \mathrel{R} 0$ and $p$ is false at $0$. For the second, use
the one-world frame with $p$ false: $\Box p$ holds vacuously while $\blacksquare p$ fails.
\end{proof}

\section{Algorithms}

\subsection{Exhaustive bounded model search}

\noindent\textbf{Input.} A formula $A$ and a bound $m$ (take $m = 2^{2\sub(A)}$ for completeness).
\noindent\textbf{Output.} A countermodel of size $\le m$, or the verdict ``valid up to $m$''.

\begin{verbatim}
for n = 1 .. m:
    for each transitive, irreflexive R on {0..n-1}:
        for each preorder T on {0..n-1}:
            if not compat(R,T): continue
            for each valuation V of the atoms of A over {0..n-1}:
                for each world w:
                    if not sat(R,T,V,A,w): return (R,T,V,w)
return "valid up to m"
\end{verbatim}

By Theorem~\ref{thm:decide}, with $m = 2^{2\sub(A)}$ the verdict ``valid up to $m$'' is equivalent
to $\vdash A$. The cost is dominated by frame enumeration, $2^{\Theta(n^2)}$ candidates per size,
so the naive procedure is doubly exponential in $\sub(A)$. It is nevertheless \emph{correct}, which
is the point of an explicit bound.

\subsection{Filtration}

\noindent\textbf{Input.} A finite model $M$ and a formula $A$.
\noindent\textbf{Output.} A model of at most $2^{\sub(A)}$ worlds agreeing with $M$ on
$\Sub(A)$.

\begin{verbatim}
Cl := Sub(A)
for each world u of M:  theta(u) := { B in Cl : M,u |= B }
W* := { theta(u) : u in M }                 # de-duplicated
R* := { (S,S') in W* x W* : FILT-R(Cl,S,S') }
T* := { (S,S') in W* x W* : FILT-T(Cl,S,S') }
V*(p) := { S in W* : p in S }
\end{verbatim}

Complexity: $O(|M| \cdot \sub(A))$ for the theories with memoised satisfaction, then
$O(|W^\ast|^2 \cdot \sub(A))$ for the relations. Legality is Theorem~\ref{thm:filt-frame};
faithfulness is Theorem~\ref{thm:filt-truth}.

\subsection{Finite canonical model construction}

\begin{verbatim}
worlds := []
for each subset t of Cl:
    if consistent(gamma(Cl,t)):  worlds.append(t)
R := { (t,s) : FILT-R(Cl,t,s) }
T := { (t,s) : FILT-T(Cl,t,s) }
V(p) := { t : p in t }
\end{verbatim}

The outer loop is over $2^{|\Cl|}$ subsets --- exactly where the bound comes from. The consistency
test can be approximated from above by cheap coherence filters that prune most subsets at once:
$\bot \notin t$; for $(B \to C) \in \Cl$ with $B,C \in \Cl$, $(B \to C) \in t$ iff
($B \notin t$ or $C \in t$); and for $\blacksquare B \in \Cl$, $\blacksquare B \in t$ implies
$B \in t$ (from $\mathbf{T}_\blacksquare$). The last is precisely what (T-refl) of
Theorem~\ref{thm:can-frame} needs; dropping it makes the constructed frame illegal, as one can
verify on the closure of $\blacksquare p \to \Box p$.

\section{How tight is the bound?}

\begin{center}
\begin{tabular}{lcccc}
\toprule
formula & $\sub$ & sharp $2^{\sub}$ & stated $2^{2\sub}$ & minimal countermodel\\
\midrule
$\Box\bot \to \bot$          & $3$ & $8$  & $64$  & $1$ world \\
$\blacksquare p \to \Box p$  & $4$ & $16$ & $256$ & $2$ worlds \\
$\Box p \to \blacksquare p$  & $4$ & $16$ & $256$ & $1$ world \\
\bottomrule
\end{tabular}
\end{center}

Ratios of $64{:}1$, $128{:}1$ and $256{:}1$. The bound is a product of \emph{depth} --- the length
of the longest $R$-chain --- and \emph{width} --- the number of worlds available at each level.
Theorem~\ref{thm:strict} pins the depth exactly: $\beta$ strictly increases along every step and is
bounded by the number of boxed subformulas, so
\[
  \text{depth of any } \Rcl\text{-chain} \ \le\ |\{\Box D \in \Sub(A)\}| \ \le\ \sub(A),
\]
a \emph{linear} bound. The entire exponential factor is therefore pure width, and width is spent
only realising distinct propositional theories over the closure --- of which the completeness
proof never needs all: it needs only the worlds actually produced by iterating
Theorems~\ref{thm:box-exists} and~\ref{thm:glob-exists} from the single refuting world.

A second, independent source of slack is the factor $2$ in the exponent of the stated bound: the
construction delivers $2^{\sub(A)}$, so $2^{2\sub(A)}$ is a square too generous before any of the
above is taken into account.

\section{Discussion and future directions}

\subsection{What the proof teaches}

\textbf{(i) L\"ob's axiom is both the obstruction and the engine.} It is why the infinite canonical
model is illegal, and why the finite one works, since it licenses the strictness clause that makes
the successor construction go through. In the filtration it appears in a third guise, as the
counting Theorem~\ref{thm:strict}: converse well-foundedness is recovered by observing that a
bounded integer cannot increase forever.

\textbf{(ii) The interaction axiom is load-bearing.} $\Box A \to \blacksquare\Box A$ is what makes
($\Box$-persistence) a legitimate clause of the filtered temporal relation, and it supplies the
corresponding hypotheses in Theorem~\ref{thm:glob-exists}. Removing it breaks the construction at
both ends simultaneously.

\textbf{(iii) Sharing the relations is an economy.} Both models use the same pair $\Rcl, \Tcl$, so
everything frame-theoretic is proved once, abstractly; only reflexivity of time needs a separate
syntactic argument in the canonical case.

\subsection{Future directions}

\begin{conjecture}[Polynomial width collapse]
For every non-derivable $A$ there is a countermodel whose world count is bounded by a polynomial in
$\sub(A)$ --- in fact by $\sub(A) + 1$ when $A$ contains no nested implications under $\Box$.
\end{conjecture}

The key insight is that the filtration measure $\beta$ strictly increases along every step of the
accessibility relation, so the \emph{depth} of any canonical countermodel is at most the number of
boxed subformulas; the exponential factor in the proved bound is pure width, and width is only ever
used to realise distinct propositional theories, which a \emph{selective} (rather than exhaustive)
canonical model never needs all of. The empirical evidence is strong: the sample formulas above
show gaps of $64{:}1$ and $128{:}1$. \emph{Test:} replace the full canonical world set by the
sub-collection actually reachable from the refuting world by iterated application of the two
existence lemmas, and bound its cardinality by the recursion depth.

Further avenues:
\begin{itemize}
  \item \emph{Complexity.} $\GL$-satisfiability is PSPACE-complete. The exact complexity of
        $\TGL$-satisfiability, and whether the interaction axiom pushes it beyond PSPACE, is open
        here.
  \item \emph{Weaker interaction.} Replacing (compat) by its converse, or by a two-sided
        commutation, and asking which combinations retain an explicitly bounded finite model
        property. The counting argument is robust; what varies is whether the temporal relation
        admits a persistence clause preserving the frame condition.
  \item \emph{Branching time.} Replacing the preorder $T$ by a tree order, or adding an
        ``eventually'' dual with its own fixed-point behaviour.
  \item \emph{Arithmetical interpretation.} Whether $\TGL$ is arithmetically complete for a
        \emph{growing} sequence of theories $T_0 \subseteq T_1 \subseteq \cdots$, with
        $\blacksquare$ read as ``at every later stage'' and $\Box$ as provability in the current
        stage. The interaction axiom is the formal counterpart of monotonicity of the sequence.
  \item \emph{Fixed points.} Whether the de Jongh--Sambin fixed point theorem has a bimodal
        analogue for $\TGL$, with the propositional variable guarded by either box.
\end{itemize}

\section{Summary of results}

\begin{enumerate}
  \item \textbf{Soundness.} Every theorem of $\TGL$ is valid on every temporal G\"odel--L\"ob
        frame. (Theorem~\ref{thm:soundness})
  \item \textbf{Strict growth of the box measure.} Every step of the filtered accessibility
        relation strictly increases the number of realised boxed subformulas; hence any frame built
        on that relation is converse well-founded, with depth at most the number of boxed
        subformulas. (Theorem~\ref{thm:strict}, Corollary~\ref{cor:wf})
  \item \textbf{Compatibility-preserving filtration.} The filtered temporal relation, strengthened
        by a $\Box$-persistence clause, preserves the interaction condition; the quotient is a legal
        frame and satisfies the filtration lemma. (Lemma~\ref{lem:compat},
        Theorems~\ref{thm:filt-frame},~\ref{thm:filt-truth})
  \item \textbf{Small model property.} Every countermodel to $A$ shrinks to one with at most
        $2^{\sub(A)}$ worlds. (Theorem~\ref{thm:small})
  \item \textbf{Existence lemmas.} Unrealised $\Box$'s and $\blacksquare$'s have witnessing
        successors in the finite canonical model. (Theorems~\ref{thm:box-exists},
        \ref{thm:glob-exists})
  \item \textbf{Weak completeness.} Validity implies derivability.
        (Theorem~\ref{thm:completeness}, Corollary~\ref{cor:iff})
  \item \textbf{Finite model property with an explicit bound.} Every non-derivable $A$ has a
        countermodel with at most $2^{\sub(A)}$, a fortiori $2^{2\sub(A)}$, worlds.
        (Theorems~\ref{thm:fmp-sharp},~\ref{thm:fmp})
  \item \textbf{Decidability.} Exhaustive bounded model search is a correct decision procedure.
        (Theorem~\ref{thm:decide})
  \item \textbf{Transitivity from L\"ob; L\"ob's rule.} $\Box A \to \Box\Box A$ is derivable without
        a transitivity axiom, and L\"ob's rule is admissible. (Theorem~\ref{thm:four})
  \item \textbf{G\"odel's second theorem and non-collapse.} $\Box\bot \to \bot$ is not a theorem,
        and neither box implies the other.
\end{enumerate}

\end{document}

